<header class="dashboard-page-header"><div><p class="dashboard-kicker"><i class="ph ph-megaphone" aria-hidden="true"></i><span>Email operations</span></p><h1>Newsletter campaigns</h1><p>Campaigns are sent only to confirmed subscribers through the durable outbox.</p></div><a class="button button--primary" href="/admin/newsletter/create"><i class="ph ph-plus" aria-hidden="true"></i><span>Create campaign</span></a></header><section class="dashboard-panel mt-8" aria-labelledby="campaigns-heading"><h2 id="campaigns-heading" class="text-xl font-bold">Campaigns</h2><?php if ($campaigns === []): ?><div class="empty-state mt-6"><i class="ph ph-envelope-simple" aria-hidden="true"></i><h3>No campaigns yet</h3><p>Create a draft when an update is ready.</p></div><?php else: ?><div class="table-shell mt-6"><table class="operations-table"><thead><tr><th>Campaign</th><th>Status</th><th>Recipients</th><th>Created</th><th>Action</th></tr></thead><tbody><?php foreach ($campaigns as $campaign): ?><tr><td data-label="Campaign"><strong><?= e($campaign['subject']) ?></strong><p class="mt-2 max-w-xl whitespace-pre-wrap text-sm text-[var(--ink-muted)]"><?= e($campaign['message']) ?></p></td><td data-label="Status"><span class="status-badge status-badge--neutral"><?= e(ucfirst($campaign['status'])) ?></span></td><td data-label="Recipients"><?= e((int) $campaign['queued_count']) ?> of <?= e((int) $campaign['recipient_count']) ?></td><td data-label="Created"><?= e($campaign['created_at']) ?></td><td data-label="Action"><?php if ($campaign['status'] === 'draft'): ?><form method="post" action="/admin/newsletter/<?= e($campaign['id']) ?>/queue"><input type="hidden" name="_token" value="<?= e($csrfToken) ?>"><button class="button button--compact button--primary" type="submit">Queue campaign</button></form><?php else: ?><span class="text-sm text-[var(--ink-muted)]">No action needed</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
